import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merges tailwind classes and handles conflicts
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import React from 'react';
import { cn } from '../../lib/utils';

interface BadgeProps {
  children: React.ReactNode;
  variant?: 'outline' | 'secondary' | 'gradient';
  className?: string;
}

const Badge: React.FC<BadgeProps> = ({ children, variant = 'secondary', className }) => {
  const variants = {
    outline: 'border border-white/20 text-slate-300',
    secondary: 'bg-white/10 text-slate-200',
    gradient: 'bg-gradient-to-r from-purple-500 to-blue-500 text-white border-none',
  };

  return (
    <span className={cn(
      "px-3 py-1 rounded-full text-xs font-medium transition-all duration-300",
      variants[variant],
      className
    )}>
      {children}
    </span>
  );
};

export default Badge;

import React from 'react';
import { cn } from '../../lib/utils';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'outline' | 'ghost' | 'gradient';
  size?: 'sm' | 'md' | 'lg';
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className, 
  ...props 
}) => {
  const variants = {
    primary: 'bg-white text-slate-950 hover:bg-slate-200',
    outline: 'border border-white/20 hover:bg-white/5 text-white',
    ghost: 'hover:bg-white/10 text-white',
    gradient: 'bg-gradient-to-r from-purple-600 to-blue-500 hover:opacity-90 text-white border-none shadow-lg shadow-purple-500/20',
  };

  const sizes = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-6 py-2.5 text-base',
    lg: 'px-8 py-4 text-lg font-semibold',
  };

  return (
    <button 
      className={cn(
        "rounded-xl transition-all duration-300 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2",
        variants[variant],
        sizes[size],
        className
      )}
      {...props}
    >
      {children}
    </button>
  );
};

export default Button;

